  "Everything is answering right now. If something stops, it shows up here, and its card shows up on Home.":
    "W tej chwili wszystko odpowiada. Jeśli coś przestanie, pojawi się tutaj, a jego kafelek pojawi się na Stronie głównej.",
  "For those hours Home Assistant doesn't keep the house consumption, so we can't tell how much came from the sun. The band is right all the same.":
    "Dla tych godzin Home Assistant nie przechowuje zużycia domu, więc nie wiadomo, ile pochodziło ze słońca. Strefa jest natomiast prawidłowa.",
  "From the sun:": "Ze słońca:",
  "From these watts up the unit is on, below it is off. “My air conditioner draws 7 W while off”: with 20 written here, those 7 W stay off. Empty = the entity state decides, as before.":
    "Od tylu watów w górę jednostka jest włączona, poniżej wyłączona. „Mój klimatyzator pobiera 7 W, gdy jest wyłączony”: przy 20 wpisanym tutaj te 7 W to nadal wyłączony. Puste = decyduje stan encji, jak dotychczas.",
