    "Jedno dotknięcie wyłącza pozycję: pozostaje skonfigurowana i znika z okna urządzenia — od razu spośród odczytów, stanów i sterowania, bo to ta sama encja. Domyślnie widać wszystko, a to, co integracja opublikuje jutro, pojawi się samo.",
