  "The presence sensors that belong to this panel: switch on the ones that are zones and leave the rest off. The Security page lists only the ones you switch on under “Zones”, and shows nothing at all while none is on.":
    "Czujniki obecności należące do tej centrali: włącz te, które są strefami, a pozostałe zostaw wyłączone. Strona Bezpieczeństwo wymienia w sekcji „Strefy” tylko te włączone, a dopóki żaden nie jest włączony, nie pokazuje nic.",
  "The radar above is a separate thing and works on its own.":
    "Radar powyżej to zupełnie inna rzecz i działa niezależnie.",
  "The sensors the appliance publishes that the fields above do not cover — air temperature and residual humidity of a dryer, a second door on a fridge: sensor.*, binary_sensor.*, number.* entities. They show up in the appliance window, with their own name and unit, in the order you add them.":
    "Czujniki udostępniane przez urządzenie, których nie obejmują pola powyżej — temperatura powietrza i wilgotność resztkowa suszarki, drugie drzwi lodówki: encje sensor.*, binary_sensor.*, number.*. Pojawiają się w oknie urządzenia, z własną nazwą i jednostką, w kolejności dodawania.",
  "The top strip — hamburger, house name, weather — stays put while the rest of the dashboard scrolls under it. This device only.":
    "Górny pasek — menu, nazwa domu, pogoda — pozostaje na miejscu, a reszta pulpitu przewija się pod nim. Tylko na tym urządzeniu.",
  "The watt sensor of the plug the unit sits under. With the threshold below, it is the one that says whether the unit is running: an air conditioner driven by a plug knows it better than its own thermostat.":
    "Czujnik watów gniazdka, do którego podłączona jest jednostka. Z progiem poniżej to on mówi, czy jednostka pracuje: klimatyzator sterowany gniazdkiem wie to lepiej niż własny termostat.",
  "There are ${quante} configured cameras that are not shown here now.":
    "Jest ${quante} skonfigurowanych kamer, których teraz tu nie widać.",
  "There is 1 configured camera that is not shown here now.":
    "Jest 1 skonfigurowana kamera, której teraz tu nie widać.",
  "There is no reading for this load right now.": "Na razie nie ma odczytu dla tego obciążenia.",
  "They cost nothing at any hour, and the euros above are only on what it took from the grid.":
    "Nie kosztują nic o żadnej godzinie, a złotówki powyżej dotyczą tylko tego, co pobrał z sieci.",
  "They stay written here so you know they exist. The bell puts them back in the warning, if they are still silent.":
    "Zostają tu zapisane, żeby było wiadomo, że są. Dzwonek przywraca je do ostrzeżenia, jeśli wciąż milczą.",
  "This dashboard's configuration is reserved for its administrator.":
    "Konfiguracja tego pulpitu jest zarezerwowana dla jego administratora.",
  "This entity is not present in this home.": "Tej encji nie ma w tym domu.",
  "This is an energy meter (kWh): it says how much it has consumed overall, not how much it is drawing right now. It is ignored here — it belongs in the “Total energy for history and Report” field.":
    "To licznik energii (kWh): mówi, ile zużyto łącznie, a nie ile pobiera teraz. Tutaj jest pomijany — jego miejsce to pole „Energia całkowita dla historii i raportu”.",
  "This sensor declares no unit of measurement: the card only shows W or kW sensors, and ignores this one.":
    "Ten czujnik nie podaje jednostki miary: karta pokazuje tylko czujniki w W lub kW i ten pomija.",
  "This sensor measures in “${misura}”: the card only shows W or kW sensors, and ignores this one.":
    "Ten czujnik mierzy w „${misura}”: karta pokazuje tylko czujniki w W lub kW i ten pomija.",
  "This weather entity has no forecast": "Ta encja pogodowa nie podaje prognozy",
  "To play": "Do odtworzenia",
  "Turn it off and the camera panel disappears from the Security page, leaving the alarm and the openings alone. The cameras stay configured: they come back by turning this on again.":
    "Wyłącz je, a panel kamer zniknie ze strony Bezpieczeństwo, nie ruszając alarmu ani otworów. Kamery pozostają skonfigurowane: wracają po ponownym włączeniu tego.",
  "Turn it off if this house has no panels: the Energy page stops showing production and self-sufficiency, and keeps consumption, costs and time bands. The entities written below stay where they are.":
    "Wyłącz ją, jeśli w tym domu nie ma paneli: strona Energia przestaje pokazywać produkcję i samowystarczalność, a zostawia zużycie, koszty i strefy czasowe. Encje wpisane poniżej zostają tam, gdzie są.",
  "Vehicle kind": "Rodzaj pojazdu",
  Vehicles: "Pojazdy",
  "Vertical swing": "Żaluzje pionowe",
  "Water softener": "Zmiękczacz wody",
  "What lights the card up": "Co podświetla kartę",
  "One tap picks it: while that entity is on, the appliance card and its Home tile take on a colour so you notice them. None is picked by default — a fridge opened to get the milk is not a fault — but the garage freezer door, or the washing machine finishing, belong here.":
    "Jedno dotknięcie wybiera: dopóki ta encja jest włączona, karta urządzenia i jej kafelek na Home przybierają kolor, żeby rzucały się w oczy. Domyślnie nie jest wybrana żadna — lodówka otwarta po mleko to nie awaria — ale drzwi zamrażarki w garażu albo koniec prania trafiają tutaj.",
  "What to show in the window": "Co pokazywać w oknie",
  "Where it is configured": "Gdzie się to ustawia",
  "Where we are": "Gdzie jesteśmy",
  "Which band it draws in": "W której strefie pobiera",
  "Which rooms show up on Home, with the temperature and how many things are on: one tap takes you into the room. As many as you like; none ticked means no block at all.":
    "Które pokoje widać na ekranie głównym, z temperaturą i liczbą włączonych rzeczy: jedno dotknięcie wprowadza do pokoju. Ile chcesz; bez żadnego zaznaczonego blok nie istnieje.",
  "Windows and shutters": "Okna i rolety",
  "Zones and entry points of the panel": "Strefy i wejścia centrali",
  "at least": "co najmniej",
  "climate first": "klima wcześniej",
  "for ${giorni} days": "od ${giorni} dni",
  "for ${minuti} min": "od ${minuti} min",
  "for ${ore} h": "od ${ore} godz",
  "from before": "sprzed",
  GdANav: "GdANav",
  "GdANav Premium is needed.": "Potrzebny jest GdANav Premium.",
  "included here: the counter had already made them before its statistics began":
    "wliczone tutaj: licznik zarejestrował je, zanim zaczęły się jego statystyki",
  "leave at": "wyjazd o",
  "no longer in this house": "nie ma go już w tym domu",
  "no longer warns": "już nie ostrzega",
  "not a flood sensor": "to nie czujnik zalania",
  "not in Home Assistant": "nie ma go w Home Assistancie",
  "printer to check": "drukarka do sprawdzenia",
  "printers to check": "drukarki do sprawdzenia",
  stop: "postój",
  stops: "przystanki",
  "update pending": "aktualizacja oczekuje",
  "updates pending": "aktualizacje oczekują",
  "tap the option to set": "dotknij opcji, aby ją ustawić",
  "this entity is read-only, it can't be switched on. The switch needs a switch, a socket or a fan.":
    "tę encję można tylko odczytać, nie da się jej włączyć. Do przełącznika potrzebny jest switch, gniazdko albo fan.",
  "this isn't a Home Assistant entity. It's written domain.name, for example switch.ventola_inverter.":
    "to nie jest encja Home Assistant. Zapisuje się ją jako domena.nazwa, na przykład switch.ventola_inverter.",
  "this menu does not list its options": "to menu nie podaje swoich opcji",
  "to full": "do pełna",
  "with traffic": "z ruchem",
  "— chosen each time, from the popup —": "— wybierana za każdym razem, z okienka —",
  "“${righe[0].name}” is not answering ${righe[0].value}.":
    "„${righe[0].name}” nie odpowiada ${righe[0].value}.",
  "🎚️ This entity is a dropdown: the button opens a popup with its options. Or fix one here.":
    "🎚️ Ta encja to lista rozwijana: przycisk otwiera okienko z jej opcjami. Albo ustaw jedną tutaj.",
  "💾 Zones saved": "💾 Strefy zapisane",
