  "(bottom left)": "(na dole po lewej)",
  "(cover entities). They appear on the 🪟 Windows page, grouped by floor and room.":
    "(encje cover). Pojawiają się na stronie 🪟 Okna, pogrupowane według piętra i pokoju.",
  "(enables automatic room grouping).": "(włącza automatyczne grupowanie według pokoju).",
  "(optional): only this HA user will see the ⚙️ Configuration page. Leave it empty to show it to everyone.":
    "(opcjonalnie): tylko ten użytkownik HA zobaczy stronę ⚙️ Konfiguracja. Zostaw puste, aby pokazać ją wszystkim.",
  "(with HACS it survives updates).": "(z HACS przetrwa aktualizacje).",
  "+${extra} more items": "+${extra} kolejnych pozycji",
