  "Fireplace pump": "Pompa kominkowa",
  "First configure the circles connected to Home. Each circle can use a direct power sensor or automatically sum every child of a load group. Then create the appliances inside each group. Empty or disabled nodes are not forced into the flow.":
    "Najpierw skonfiguruj kółka połączone z Domem. Każde kółko może korzystać z bezpośredniego czujnika mocy albo automatycznie sumować wszystkie odbiorniki swojej grupy. Potem utwórz urządzenia wewnątrz każdej grupy. Puste lub wyłączone węzły nie są wpychane do przepływu.",
  "First select your lights in the Lights step (or wizard).":
    "Najpierw wybierz swoje światła w kroku Światła (albo w kreatorze).",
  Fixed: "Stały",
  "Fixed cycle duration (minutes)": "Stały czas cyklu (minuty)",
  "Flap opened": "Klapa otwarta",
  "Flightradar24 exposes “current in area”: the count, with the list of flights in the attributes.":
    "Flightradar24 podaje „current in area”: liczbę, z listą lotów w atrybutach.",
  "Flights in the area": "Loty w okolicy",
  "Flights overhead": "Samoloty nad domem",
  "Flip the direction (ON = closed)": "Odwróć kierunek (ON = zamknięte)",
  "Flip the percentages (100 = closed)": "Odwróć procenty (100 = zamknięte)",
  Flood: "Zalanie",
  Floods: "Zalania",
  Floor: "Piętro",
  "Floor (opt.)": "Piętro (opc.)",
  "Floor icon": "Ikona piętra",
  Flow: "Zasilanie",
  "Flow temperature": "Temperatura zasilania",
  "Flow · Return · Pressure": "Zasilanie · Powrót · Ciśnienie",
  "Flue extractor fan": "Wyciąg spalin",
  "Flue gas": "Spaliny",
  "Flue gas fan": "Wentylator spalin",
  "Flue gas temperature": "Temperatura spalin",
  "Followed train": "Śledzony pociąg",
  Food: "Karma",
  "Food level": "Poziom karmy",
  "Food running low": "Karma się kończy",
  "For each item enter": "Przy każdej pozycji wpisz",
  "For every source, Total energy meter is the cumulative Recorder source (normally state_class: total_increasing). It is not a period value: day, month and year are calculated as final Recorder sum minus initial Recorder sum, so meter resets are preserved. Period sensors are optional current-period overrides.":
    "Dla każdego źródła licznik energii całkowitej to sumaryczne źródło Recordera (zwykle state_class: total_increasing). Nie jest to wartość okresowa: dzień, miesiąc i rok liczone są jako końcowa suma Recordera minus suma początkowa, więc zerowania licznika są zachowane. Czujniki okresowe to opcjonalne nadpisania bieżącego okresu.",
  "For fridge and freezer: shows the temperature strip instead of the power bar.":
    "Dla lodówki i zamrażarki: pokazuje pasek temperatury zamiast paska mocy.",
  "For lights you only want to see, with no accidental taps: the row stays where it is, the button stops responding.":
    "Dla świateł tylko do podglądu, bez przypadkowych dotknięć: wiersz zostaje na miejscu, przycisk przestaje reagować.",
  "For sockets that must not be switched off: the fridge, the modem, the freezer. The row stays where it is, the button stops responding.":
    "Do gniazdek, których nie wolno wyłączać: lodówka, modem, zamrażarka. Wiersz zostaje na miejscu, przycisk przestaje reagować.",
  "For this window only: resting at this percentage or below counts as closed. Empty, the house threshold at the top applies.":
    "Tylko dla tego okna: zatrzymanie na tym procencie lub niżej liczy się jako zamknięte. Puste — obowiązuje próg domu u góry.",
  "For this window only: when its room's humidity goes above this level, the card says to open it to air out. Empty, the house threshold at the top applies; zero turns the advice off on this window.":
    "Tylko dla tego okna: gdy wilgotność jego pokoju przekroczy ten poziom, karta mówi, by je otworzyć i przewietrzyć. Puste — obowiązuje próg domu wpisany u góry; zero wyłącza radę dla tego okna.",
  "For those without a panel: an alarm built with ESPHome, with scripts or with a list of modes. Each button below shows up in the Security section and on the Home tile, next to the panel's own — and when there is no panel, in their place.":
    "Dla tych bez centrali: alarm zbudowany na ESPHome, na skryptach albo na liście trybów. Każdy przycisk poniżej pojawia się w sekcji Bezpieczeństwo i na kafelku Home, obok tych centrali — a gdy centrali nie ma, zamiast nich.",
  "For what recharges instead of being replaced: the wall tablet, a power bank. The two entities are number.* or input_number.*, the ones the device exposes to say where it starts again and where it stops. Leave them empty and this stays a battery like the others.":
    "Dla tego, co się ładuje zamiast być wymieniane: tablet na ścianie, powerbank. Obie encje to number.* lub input_number.* — te, które urządzenie udostępnia, by powiedzieć, gdzie zaczyna od nowa i gdzie się zatrzymuje. Zostaw je puste, a to pozostanie baterią jak każda inna.",
  "Force (ignore rain)": "Wymuś (ignoruj deszcz)",
  Forest: "Las",
  "Found next to the appliance — one tap adds them:":
    "Znalezione obok urządzenia — jedno dotknięcie je dodaje:",
