  "Fountain filter": "Filtr poidełka",
  "Four sensors of your choosing: the ones you actually read to decide, not a house average. The typical one is outdoors, the one you go by for the indoor units. The unit comes from Home Assistant, and a sensor you do not name is a pill that does not show up.":
    "Cztery czujniki wybrane przez ciebie: te, które naprawdę sprawdzasz, żeby zdecydować, a nie średnia domu. Typowy jest ten na zewnątrz, ten, według którego ustawiasz jednostki wewnętrzne. Jednostkę podaje Home Assistant, a czujnik, którego nie wskażesz, to kafelek, który się nie pojawi.",
