  Good: "Dobre",
  "Good up to the first, fair up to the second, poor up to the third, bad beyond. The defaults are the norms: the European index bands for particulates and gases, EN 16798-1 for CO₂, the WHO guidelines for monoxide. Change them only if you know why.":
    "Dobra do pierwszego, umiarkowana do drugiego, zła do trzeciego, bardzo zła powyżej. Domyślnie są to normy: pasma europejskiego indeksu dla pyłów i gazów, EN 16798-1 dla CO₂, wytyczne WHO dla tlenku węgla. Zmieniaj je tylko, jeśli wiesz dlaczego.",
