  "It changes the drawing at the other end of the pipe: whoever has a boiler serving only the tank was shown a radiator they do not have.":
    "Zmienia rysunek na drugim końcu rury: kto ma kocioł obsługujący tylko zasobnik, widział grzejnik, którego nie ma.",
  "It did not work.": "Nie udało się.",
