  "Off / Closed (off)": "Wyłączone / Zamknięte (off)",
  "Off, the weather entity above is enough: temperature, humidity and wind come from it.":
    "Wyłączone: wystarczy encja weather powyżej — temperatura, wilgotność i wiatr są z niej czytane.",
