  On: "Włączone",
  "On / Active / Open (on)": "Włączone / Aktywne / Otwarte (on)",
  "On Home": "Na stronie głównej",
  "On battery": "Na akumulatorze",
  "On battery · ${carica}%": "Na akumulatorze · ${carica}%",
  "On cards show the room temperature big (target below)":
    "Na kartach pokazuj dużą temperaturę pokoju (cel poniżej)",
  "On mains": "Na sieci",
  "On time": "Punktualnie",
  "On which page": "Na której stronie",
  "On, the radar plays the last hour of rain: you see which way the front is moving, not only where it is now. That is six frames instead of one, so six rounds of tiles: turn it off on a slow connection, or if you prefer a single image.":
    "Włączony radar odtwarza ostatnią godzinę deszczu: widać, dokąd idzie front, a nie tylko gdzie jest teraz. To sześć klatek zamiast jednej, czyli sześć rund kafelków: wyłącz przy wolnym łączu albo jeśli wolisz jeden obraz.",
  "On/off control": "Sterowanie wł./wył.",
  "On/off · Brightness · Colour": "Wł./wył. · Jasność · Kolor",
  "On/off · Consumption · Room by room": "Wł./wył. · Zużycie · Pokój po pokoju",
  "One bin per material, and for each the sensor that says when the collection comes: the page answers the evening question — what do I put out tonight — and the Home tile lights up the day before. Whoever has a single calendar, with one event per collection, puts it in the box at the bottom.":
    "Jeden kosz na frakcję, a dla każdego czujnik, który mówi, kiedy przyjeżdża odbiór: strona odpowiada na wieczorne pytanie — co wystawić dziś wieczorem — a kafelek Home zapala się dzień wcześniej. Kto ma jeden kalendarz, z jednym wydarzeniem na odbiór, wpisuje go w polu na dole.",
  "One room at a time · Scenes · Sensors": "Jeden pokój naraz · Sceny · Czujniki",
  "One single tile": "Tylko jeden kafelek",
  "One step, and you will never be asked again: open github.com/login/device and type this code.":
    "Jeden krok i nikt cię o to więcej nie poprosi: otwórz github.com/login/device i wpisz ten kod.",
  "One tile per plant": "Po jednym na instalację",
  "One window can carry all three: fill in the boxes you have, the box tells the type.":
    "Na jednym oknie mogą być wszystkie trzy: wypełnij pola, które masz — pole samo mówi, jaki to typ.",
  "Only daily sensors or Recorder deltas from cumulative total meters are counted. Lifetime values are never added directly.":
    "Liczone są tylko czujniki dzienne albo różnice Recordera z sumarycznych liczników całkowitych. Wartości całkowite nigdy nie są dodawane wprost.",
  "Only if you already have a helper measuring the period. Without one, the period comes from the total meter.":
    "Tylko jeśli masz już helper mierzący okres. Bez niego okres pochodzi z licznika sumarycznego.",
  "Only needed when the shutter is driven by two relays — one that sends it up, one that sends it down — like a Shelly left in switch mode: then “Close” switches this one on, and “Stop” switches both off. With a real cover.* leave it empty.":
    "Potrzebne tylko wtedy, gdy roletą sterują dwa przekaźniki — jeden podnosi, drugi opuszcza — jak w Shelly zostawionym w trybie przełącznika: wtedy „Zamknij” włącza ten, a „Zatrzymaj” wyłącza oba. Przy prawdziwym cover.* zostaw puste.",
  "Only rooms containing a light are shown. Edit opens all light fields, not a browser prompt. The pills say what each light can do — RGB, tunable white, dimmer or plain on/off — and that is what drives the controls in the popup.":
    "Pokazywane są tylko pomieszczenia zawierające światło. Edycja otwiera wszystkie pola światła, a nie okienko przeglądarki. Plakietki mówią, co potrafi każde światło — RGB, regulowana biel, ściemniacz albo zwykłe wł./wył. — i to decyduje o sterowaniu w oknie.",
  "Only the modes the panel actually accepts are listed. Removing one hides it from the section and changes nothing about what the panel can do; disarm always stays.":
    "Są tu tylko tryby, które centrala naprawdę przyjmuje. Usunięcie jednego ukrywa go w sekcji i niczego nie zmienia w tym, co centrala potrafi; rozbrojenie zostaje zawsze.",
  "Only with the soil below (%)": "Tylko gdy gleba poniżej (%)",
