  "You entered entities in this section without saving them. If you leave now, they will be lost.":
    "Wprowadzono encje w tej sekcji bez zapisania. Jeśli teraz wyjdziesz, zostaną utracone.",
  "Save and continue": "Zapisz i kontynuuj",
  "Leave without saving": "Wyjdź bez zapisywania",
  "Stay here": "Zostań tutaj",
  "Nobody home": "Nikogo nie ma w domu",
  "Big buttons: a dashboard action or any entity (a scene, a script, a button). For each one the name on the tablet, the line below and the drawing.":
    "Duże przyciski: akcja panelu lub dowolna encja (scena, skrypt, przycisk). Dla każdego nazwa na tablecie, wiersz poniżej i rysunek.",
  "Full config": "Pełna konfiguracja",
  "On, a light added to the room in the source dashboard shows up by itself. Off, the slots are chosen here: any entity or action, with the name and drawing you want.":
    "Włączone: światło dodane do pokoju w panelu źródłowym pojawi się samo. Wyłączone: miejsca wybiera się tutaj – dowolna encja lub akcja, z wybraną nazwą i rysunkiem.",
  "Slots of your own: in each one any Home Assistant entity — a light, a socket, a lock, a sensor — or a dashboard action, with the name and drawing you want.":
    "Miejsca tylko twoje: w każdym dowolna encja Home Assistant – światło, gniazdko, zamek, czujnik – lub akcja panelu, z wybraną nazwą i rysunkiem.",
  "A dehumidifier is not a thermostat: pick its humidifier entity and the Climate page gives it a card of its own, with the current humidity, the target, the modes, the fan and the tank-full warning. The other fields fill themselves in when you save.":
    "Osuszacz to nie termostat: wybierz jego encję humidifier, a strona Klimat da mu własną kartę z bieżącą wilgotnością, celem, trybami, wentylatorem i ostrzeżeniem o pełnym zbiorniku. Pozostałe pola wypełnią się same przy zapisie.",
