  Shutters: "Rolety",
  "Shutters and curtains show up on the 🪟 Windows page, grouped by floor and room. Every row accepts a cover.* entity — with position and percentages — or a switch.* relay: one when switching it on keeps the shutter up, two when one relay sends it up and another sends it down, like a Shelly in switch mode. When the window opens by hand — shutters, blinds, a handle — leave the command boxes empty and fill in the contact sensor alone: the card still draws it and says whether it is open.":
    "Rolety i zasłony pojawiają się na stronie 🪟 Okna, pogrupowane według piętra i pokoju. Każdy wiersz przyjmuje encję cover.* — z pozycją i procentami — albo przekaźnik switch.*: jeden, gdy po włączeniu roleta zostaje w górze, dwa, gdy jeden podnosi, a drugi opuszcza, jak Shelly w trybie przełącznika. Jeśli okno otwiera się ręcznie — okiennice, żaluzje, klamka — zostaw pola sterowania puste i wypełnij tylko czujnik otwarcia: karta i tak zostanie narysowana i powie, czy jest otwarte.",
  "Shutters · Curtains · Contact sensors": "Rolety · Zasłony · Czujniki otwarcia",
  "Sign path timeout": "Przekroczono czas podpisywania ścieżki",
  "Simple alternative to the duration entity.": "Prosta alternatywa dla encji czasu trwania.",
