  "Small pool": "Mały basen",
  "Smart thermostats publish the heating mode on a separate entity: TADO has Home and Away, others add Holiday or Boost. The card shows it, and if the entity is a select or an input_select you can change it right there.":
    "Inteligentne termostaty udostępniają tryb ogrzewania w osobnej encji: TADO ma W domu i Poza domem, inne dodają Wakacje albo Boost. Karta go pokazuje, a jeśli encja to select lub input_select, można go tam od razu zmienić.",
  "SmartThings, Sonos, Chromecast, AirPlay… pick the device and the player arrives ready-made: its entity, the controls the integration publishes next to it — a TV's power switch, the input dropdown — and its readings. Or, below, one field at a time.":
    "SmartThings, Sonos, Chromecast, AirPlay… wybierz urządzenie, a odtwarzacz przyjdzie gotowy: jego encja, sterowanie publikowane obok — wyłącznik telewizora, lista źródeł — i odczyty. Albo niżej, pole po polu.",
