  "Turn everything on": "Włącz wszystko",
  "Turn it off to open on the first tap: whoever opens their own front door ten times a day knows the confirmation by heart. A PIN is not a confirmation and stays: a protected door keeps asking for it.":
    "Wyłącz je, by otwierać pierwszym dotknięciem: kto otwiera własną bramę dziesięć razy dziennie, zna potwierdzenie na pamięć. PIN nie jest potwierdzeniem i zostaje: chronione drzwi nadal o niego proszą.",
  "Turn off": "Wyłącz",
  "Turn on": "Włącz",
  "Turn on or off": "Włącz lub wyłącz",
  "Turn on/off": "Włącz/wyłącz",
  "Turn the boiler on or off": "Włącz lub wyłącz kocioł",
  "Turning them on and off": "Włączanie i wyłączanie",
  Tuxedo: "Smoking",
  "Two shots of the same car: the dashboard shows the plugged-in one while it charges and the other one the rest of the time. The first is enough — without the second it simply stays.":
    "Dwa zdjęcia tego samego samochodu: panel pokazuje to z podłączoną wtyczką podczas ładowania, a drugie przez resztę czasu. Pierwsze wystarczy — bez drugiego po prostu zostaje.",
  "Two weeks that repeat, written by hand: tap a day and pick what goes out. No sensor and no Home Assistant calendar needed — the page and the Home tile read this exactly as they would read an integration. A material that already has its own sensor above is not repeated: the sensor wins.":
    "Dwa tygodnie, które się powtarzają, wpisane ręcznie: dotknij dnia i wybierz, co wystawiasz. Nie potrzeba żadnego czujnika ani kalendarza Home Assistant — strona i kafelek na Home czytają to dokładnie tak, jak czytałyby integrację. Frakcja, która ma już swój czujnik powyżej, nie powtarza się: decyduje czujnik.",
  Type: "Typ",
  "Type / artwork": "Typ / ilustracja",
  "Type at least two letters: it searches every tab at once.":
    "Wpisz co najmniej dwie litery: szuka we wszystkich zakładkach naraz.",
  "Type the code…": "Wpisz kod…",
  "Type your question…": "Napisz swoje pytanie…",
