  "New plant": "Nowa roślina",
  "No plant configured": "Brak skonfigurowanych roślin",
  "Optional: the temperature sensor in the same pot. Leave it empty if yours only measures moisture.":
    "Opcjonalnie: czujnik temperatury w tej samej doniczce. Zostaw puste, jeśli twój mierzy tylko wilgotność.",
  outdoors: "na zewnątrz",
  "Outdoors: if rain is coming, wait": "Na zewnątrz: jeśli nadchodzi deszcz, poczekaj",
  "Plant care": "Rośliny",
  "Plant saved": "Roślina zapisana",
  "Rain expected today: ${quanta}": "Dziś prognozowany deszcz: ${quanta}",
  "Rain in ${ore} hours: ${quanta}": "Deszcz za ${ore} godz.: ${quanta}",
  "Rain on its way: ${quanta}": "Nadchodzi deszcz: ${quanta}",
  "Rain within the hour: ${quanta}": "Deszcz w ciągu godziny: ${quanta}",
  "Save this plant": "Zapisz roślinę",
  "Soil · When to water": "Gleba · Kiedy podlać",
  "Soil at ${quanto}": "Gleba: ${quanto}",
  "Soil temperature": "Temperatura gleby",
  "Take the ${quante} soil sensors Home Assistant found":
    "Weź czujniki gleby znalezione przez Home Assistant: ${quante}",
  "The plants at home, one per row: the soil moisture sensor, the name, the drawing, and the temperature if there is one. The Plant care page says which need watering, which are waiting for rain and when the others will be due.":
    "Rośliny w domu, po jednej w wierszu: czujnik wilgotności gleby, nazwa, rysunek i, jeśli jest, temperatura. Strona Rośliny mówi, które trzeba podlać, które czekają na deszcz i kiedy przyjdzie kolej na pozostałe.",
  "The rain will see to it": "Deszcz się tym zajmie",
  "The sensor stuck in the soil, in percent: Ecowitt, Tuya, Xiaomi.":
    "Czujnik wbity w glebę, w procentach: Ecowitt, Tuya, Xiaomi.",
  "too wet": "za mokro",
  "Too wet above (%)": "Za mokro powyżej (%)",
  "Unnamed plant": "Roślina bez nazwy",
  "Until you pick the entity this plant is nowhere: not on the page, not on the Home tile.":
    "Dopóki nie wybierzesz encji, tej rośliny nigdzie nie ma: ani na stronie, ani na kafelku ekranu głównego.",
  Waiting: "Czeka",
  "watered just now": "właśnie podlana",
  "When the soil is dry but the home weather forecasts rain in the next hours, the plant waits instead of asking for water. Only for those the rain really reaches.":
    "Gdy gleba jest sucha, ale pogoda domu przewiduje deszcz w najbliższych godzinach, roślina czeka, zamiast prosić o wodę. Tylko dla tych, do których deszcz naprawdę dociera.",
  "${quante} readings out of range": "Wartości poza zakresem: ${quante}",
  "${ritardo} days late": "${ritardo} dni spóźnienia",
  "After this many days the page and the Home tile say the water change is due.":
    "Po tylu dniach strona i kafelek ekranu głównego mówią, że trzeba wymienić wodę.",
  "All in range": "Wszystko w normie",
