  "Not recorded yet: tap “Done today” on the day you do it, and from then on the page counts the days.":
    "Jeszcze nie zapisano: dotknij „Zrobione dziś” w dniu wymiany, a od tej pory strona będzie liczyć dni.",
  "one day late": "dzień spóźnienia",
