  "${nome}: the TV takes the keys itself, no remote needed.":
    "${nome}: telewizor sam odbiera przyciski, pilot nie jest potrzebny.",
  "${nome}: the arrows, OK and the other keys show under the card while the TV is on.":
    "${nome}: strzałki, OK i pozostałe przyciski pojawiają się pod kartą, gdy telewizor jest włączony.",
  "A remote.* entity is required.": "Wymagana jest encja remote.*.",
  "Arrow down": "Strzałka w dół",
  "Arrow left": "Strzałka w lewo",
  "Arrow right": "Strzałka w prawo",
  "Arrow up": "Strzałka w górę",
  "Asking Home Assistant which integration it is…":
    "Pytam Home Assistant, z której integracji pochodzi…",
  "Next channel": "Następny kanał",
  "Previous channel": "Poprzedni kanał",
  "Remote control": "Pilot",
  "TV home screen": "Ekran główny telewizora",
  "TV menu": "Menu telewizora",
  "The TV's arrows, OK, back, home screen and channels, under its card and only while the TV is on. It needs the TV's remote.* entity: Samsung (Samsung Smart TV integration), Sony Bravia, Philips, Android TV and Google TV, Apple TV, Roku. LG webOS TVs don't need it.":
    "Strzałki, OK, wstecz, ekran główny i kanały telewizora, pod jego kartą i tylko gdy jest włączony. Potrzebna jest encja remote.* telewizora: Samsung (integracja Samsung Smart TV), Sony Bravia, Philips, Android TV i Google TV, Apple TV, Roku. Telewizory LG webOS jej nie potrzebują.",
  "These are in the house — one tap picks it:": "Te są w domu — jedno dotknięcie go wybiera:",
  "Volume down": "Ciszej",
  "Volume up": "Głośniej",
  "${quante} actions": "Akcje: ${quante}",
  "${quante} areas together: the buttons apply to all":
    "Strefy razem: ${quante} – przyciski działają na wszystkie",
  "Press and hold an area to pick more than one": "Przytrzymaj strefę, aby wybrać więcej niż jedną",
  "1 action": "1 akcja",
  "Close the ${nome} group": "Zwiń grupę ${nome}",
  "Open the ${nome} group": "Rozwiń grupę ${nome}",
  "The group is optional: actions with the same group sit together on Home, under a title that says how many are on and closes with a tap. Without groups it stays a single row.":
    "Grupa jest opcjonalna: akcje z tą samą grupą są razem na Home, pod tytułem, który mówi, ile jest włączonych, i zwija się jednym dotknięciem. Bez grup zostaje jeden rząd.",
  "e.g. Lights, Shutters": "np. Światła, Rolety",
  "💾 Group saved": "💾 Grupa zapisana",
  "1 open · tap to close": "1 otwarta · dotknij, aby zamknąć",
  "open · tap to close": "otwarte · dotknij, aby zamknąć",
  "1 open now · closed by hand": "1 otwarte teraz · zamyka się ręcznie",
  "open now · closed by hand": "otwarte teraz · zamyka się je ręcznie",
  "1 unlocked · tap to lock": "1 odblokowany · dotknij, aby zablokować",
  "unlocked · tap to lock": "odblokowane · dotknij, aby zablokować",
  "Door or window": "Drzwi czy okno",
  Doors: "Drzwi",
  Locks: "Zamki",
  "lock unlocked": "zamek odblokowany",
  "locks unlocked": "zamki odblokowane",
  "shutter open": "roleta otwarta",
  "shutters open": "rolety otwarte",
  "Under the weather, open doors and open windows are two pills. By default the class Home Assistant gives the contact decides; pick here when it is not the right one.":
    "Pod pogodą otwarte drzwi i otwarte okna to dwie pigułki. Domyślnie decyduje klasa, którą Home Assistant nadaje czujnikowi; wybierz tutaj, gdy nie jest właściwa.",
  "If the camera already has its own integration in Home Assistant — Reolink, Tapo, Hikvision — the entity is already there: pick it in the field above, and the video goes through it.":
    "Jeśli kamera ma już własną integrację w Home Assistancie — Reolink, Tapo, Hikvision — encja już istnieje: wybierz ją w polu powyżej, a obraz pójdzie przez nią.",
  "The stream name only works with the dashboard opened outside Home Assistant: in here it cannot be reached, and the camera goes through its entity.":
    "Nazwa strumienia działa tylko wtedy, gdy pulpit jest otwarty poza Home Assistantem: stąd nie da się do niej dotrzeć, a kamera idzie przez swoją encję.",
  "HLS: skipped, Home Assistant declares no stream for this camera":
    "HLS: pominięto, Home Assistant nie deklaruje strumienia dla tej kamery",
  "WebRTC: the go2rtc stream name only works with the dashboard opened outside Home Assistant — in here the camera goes through its entity":
    "WebRTC: nazwa strumienia go2rtc działa tylko przy pulpicie otwartym poza Home Assistantem — tutaj kamera idzie przez swoją encję",
  "WebRTC: tried first with its full time, the video did not arrive":
    "WebRTC: wypróbowano najpierw z pełnym czasem, obraz nie dotarł",
  Bypass: "Zablokuj",
  "Bypass from the alarm?": "Wyłączyć z alarmu?",
