  "1 pack": "1 pakiet",
  "above the ${soglia} threshold": "powyżej progu ${soglia}",
  "Add pack": "Dodaj pakiet",
  "An entity, or the number printed on the pack label with its unit. With every pack's capacity the overall charge is weighted by energy, and the page says when it will be full or empty.":
    "Encja albo liczba z etykiety pakietu wraz z jednostką. Znając pojemność każdego pakietu, łączny poziom naładowania jest ważony energią, a strona podaje, kiedy będzie pełny lub pusty.",
  "average ${media}": "średnio ${media}",
  "Battery storage": "Magazyn energii",
  "BMS type": "Typ BMS",
  Capacity: "Pojemność",
  "Cell ${cella.numero} · ${cifre(cella.volt, 3)} V":
    "Ogniwo ${cella.numero} · ${cifre(cella.volt, 3)} V",
  "Cell ${cella.numero} · not answering": "Ogniwo ${cella.numero} · nie odpowiada",
  "Cell imbalance": "Nierównowaga ogniw",
  "Cell voltage delta": "Różnica napięć ogniw",
  Cells: "Ogniwa",
  "Cells (${celle.length})": "Ogniwa (${celle.length})",
  charge: "naładowania",
  charging: "ładowanie",
  Cycles: "Cykle",
  discharging: "rozładowanie",
  Discharging: "Rozładowywanie",
  "empty in ${quanto}": "pusty za ${quanto}",
  "Find the cells": "Znajdź ogniwa",
  "full in ${quanto}": "pełny za ${quanto}",
  health: "kondycja",
  "ideal below ${soglia}": "idealnie poniżej ${soglia}",
  "In Ah, Wh or kWh. Left empty, it is worked out from the charge and the capacity.":
    "W Ah, Wh lub kWh. Pozostawiona pusta jest obliczana z poziomu naładowania i pojemności.",
  "It recognises JK, JBD and Daly BMS and Huawei LUNA2000 batteries from their entity names and groups them by prefix. It puts them here as rows, once: from then on they are yours.":
    "Rozpoznaje BMS JK, JBD i Daly oraz baterie Huawei LUNA2000 po nazwach ich encji i grupuje je według prefiksu. Dodaje je tu jako wiersze, tylko raz: od tej pory są twoje.",
  "Optional. A battery that talks through the inverter — like the Huawei LUNA2000 with the Huawei Solar integration — has no BMS to choose: state of charge, power and energy go in Energy, “Flows & entities” tab, in the “Battery · charge” and “Battery · discharge” boxes. This tab is only for seeing the packs, or the modules, one by one.":
    "Opcjonalne. Bateria, która komunikuje się przez falownik — jak Huawei LUNA2000 z integracją Huawei Solar — nie ma BMS do wyboru: stan naładowania, moc i energię ustawia się w Energia, karta „Przepływy i encje”, w polach „Battery · charge” i „Battery · discharge”. Ta karta służy tylko do oglądania pakietów lub modułów jeden po drugim.",
  "max ${cifre(pacco.massima.volt, 3)} V · cell ${pacco.massima.numero}":
    "maks. ${cifre(pacco.massima.volt, 3)} V · ogniwo ${pacco.massima.numero}",
  "min ${cifre(pacco.minima.volt, 3)} V · cell ${pacco.minima.numero}":
    "min. ${cifre(pacco.minima.volt, 3)} V · ogniwo ${pacco.minima.numero}",
  "MOS temperature": "Temperatura MOS",
  "needs balancing": "do wyrównania",
  "Needs balancing": "Do wyrównania",
  "Needs balancing above (mV)": "Do wyrównania powyżej (mV)",
  "New pack": "Nowy pakiet",
  "No battery pack": "Brak pakietu baterii",
  "No battery pack configured": "Nie skonfigurowano pakietu baterii",
  "No cells found": "Nie znaleziono ogniw",
  "No pack answering": "Żaden pakiet nie odpowiada",
  "No reading": "Brak odczytu",
  "One cell voltage per line, in cell order. You can paste them all at once, commas work too; “Find the cells” takes them from Home Assistant using the prefix of the pack's other entities.":
    "Jedno napięcie ogniwa w wierszu, w kolejności ogniw. Możesz wkleić wszystkie naraz, także oddzielone przecinkami; „Znajdź ogniwa” pobiera je z Home Assistant według prefiksu pozostałych encji pakietu.",
  "Optional: if the BMS does not publish it, the imbalance is worked out from the cells.":
    "Opcjonalne: jeśli BMS jej nie publikuje, nierównowaga jest obliczana z ogniw.",
  "Other BMS": "Inny BMS",
  "Pack 1": "Pakiet 1",
  "Pack saved": "Pakiet zapisany",
  "Current sign": "Znak prądu",
  "Positive when charging (JK, JBD, Daly)": "Dodatni przy ładowaniu (JK, JBD, Daly)",
  "Negative when charging": "Ujemny przy ładowaniu",
  "With the sign the BMS uses: if it writes it negative while charging, pick that in “Current sign”.":
    "Ze znakiem, którego używa BMS: jeśli zapisuje prąd ujemny podczas ładowania, wybierz to w „Znak prądu”.",
  "If the page says “Discharging” while the battery is charging, your BMS writes the current the other way round: pick “Negative when charging”.":
    "Jeśli strona pokazuje „Rozładowanie”, gdy bateria się ładuje, twój BMS zapisuje prąd odwrotnie: wybierz „Ujemny przy ładowaniu”.",
  "Remaining energy": "Pozostała energia",
  "Save pack": "Zapisz pakiet",
  "State of charge (SoC)": "Poziom naładowania (SoC)",
  "State of health (SoH)": "Stan zdrowia (SoH)",
  "Take the ${quanti} packs Home Assistant found":
    "Weź pakiety znalezione przez Home Assistant: ${quanti}",
  "The pack's charge percentage: without it the pack does not show.":
    "Procent naładowania pakietu: bez niego pakiet się nie wyświetla.",
  "The storage packs and their BMS: they show in the Batteries tab of Energy and on the Battery storage tile in Home. One pack per row: its entity is the state of charge, and inside are the others — health, voltages, currents, temperatures, cycles, capacity and every single cell.":
    "Pakiety magazynu i ich BMS: widać je w karcie Baterie w Energii i na kafelku Magazyn energii na stronie głównej. Jeden pakiet w wierszu: jego encją jest poziom naładowania, a w środku są pozostałe — kondycja, napięcia, prądy, temperatury, cykle, pojemność i każde ogniwo z osobna.",
  "to the house": "do domu",
  "Unit of a hand-written capacity": "Jednostka pojemności wpisanej ręcznie",
  "Unnamed pack": "Pakiet bez nazwy",
  "Until you pick the state of charge this pack is nowhere: not in Energy, not on the Home tile.":
    "Dopóki nie wybierzesz poziomu naładowania, ten pakiet nigdzie się nie pojawi: ani w Energii, ani na kafelku strony głównej.",
  "When the highest and lowest cells are further apart than this, the pack says “Needs balancing” and the Home tile asks for attention.":
    "Gdy najwyższe i najniższe ogniwo różnią się bardziej niż ta wartość, pakiet pokazuje „Do wyrównania”, a kafelek na stronie głównej prosi o uwagę.",
  "${accese} of ${totale} lights on": "Włączone: ${accese} z ${totale} świateł",
  "${lettura.posizione}% open": "Otwarta w ${lettura.posizione}%",
  "1 of ${totale} lights on": "Włączone: 1 z ${totale} świateł",
  "Everything with its own control, in a grid": "Wszystko z własnym sterowaniem, w siatce",
  "How an open room looks on the Rooms page.":
    "Jak wygląda otwarte pomieszczenie na stronie Pomieszczenia.",
  "Room view": "Widok pomieszczenia",
  "the light is off": "światło jest wyłączone",
  "the light is on": "światło jest włączone",
  "The list split by type, as before": "Lista podzielona według typu, jak dotąd",
