  "Also on: ${nomi}": "Włączone też: ${nomi}",
  "at ${ora}": "o ${ora}",
  "Buttons in Cooking": "Przyciski w Gotowaniu",
  "Cooking — status, times, temperature and controls":
    "Gotowanie — stan, czasy, temperatura i sterowanie",
  "Cooking shows up once the appliances include an air fryer, an oven, a microwave, a cooktop or a hood.":
    "Gotowanie pojawia się, gdy wśród urządzeń jest frytkownica beztłuszczowa, piekarnik, mikrofalówka, płyta grzewcza lub okap.",
  "Cooking status": "Stan gotowania",
  Cooler: "Chłodniej",
  "done at ${ora}": "koniec o ${ora}",
