  Hotter: "Cieplej",
  "inside ${gradi}": "w środku ${gradi}",
  left: "pozostało",
  "No buttons: Cooking will only show the status and the times.":
    "Brak przycisków: Gotowanie pokaże tylko stan i czasy.",
  "Nothing cooking": "Nic się nie gotuje",
  "Nothing in the kitchen": "Nic w kuchni",
  "Nothing to fill in: filled fields stay, and nothing else was found.":
    "Nic do uzupełnienia: wypełnione pola zostają, a nic więcej nie znaleziono.",
  "of ${minuti} min": "z ${minuti} min",
  "open the drawer": "otwórz szufladę",
  "Open/closed binary_sensor. Empty: uses the “Door entity”.":
    "binary_sensor otwarte/zamknięte. Puste: używa „Encji drzwi”.",
  "Program or recipe": "Program lub przepis",
  "Ready at ${ora}": "Gotowe o ${ora}",
  "Ready in ${durata}": "Gotowe za ${durata}",
  "Ready to start": "Gotowe do startu",
  Remaining: "Pozostało",
  Resume: "Wznów",
  "Seconds, minutes or hh:mm. Empty: uses the “Program duration”.":
    "Sekundy, minuty lub gg:mm. Puste: używa „Czasu trwania programu”.",
  "Seconds, minutes, hh:mm or the end time. Empty: uses the “Remaining time”.":
    "Sekundy, minuty, gg:mm lub godzina końca. Puste: używa „Pozostałego czasu”.",
  "started at ${partita}": "uruchomione o ${partita}",
  "The controls show up when cooking starts": "Przyciski pojawiają się, gdy zaczyna się gotowanie",
  "The entity_id given to services that do not name one. Empty: the cooking status.":
    "entity_id przekazywane usługom, które nie podają własnego. Puste: stan gotowania.",
  "The rest of the kitchen": "Reszta kuchni",
  "The temperature sensor.": "Czujnik temperatury.",
  "The timer is stopped until it resumes": "Czas stoi, dopóki nie wznowisz",
  "Time and temperature set: it only needs starting":
    "Czas i temperatura wybrane: brakuje tylko startu",
  "Total time": "Czas całkowity",
  "under a minute": "mniej niż minuta",
  "What the “Cooking” entry of Appliances reads and presses. A control is an entity (button, switch, number, script) or a service with its parameters: philips_airfryer.adjust_time time=60 method=add. A button only shows up when its field is filled in, and only if it answers.":
    "Co pozycja „Gotowanie” w Urządzeniach odczytuje i naciska. Sterowanie to encja (button, switch, number, script) albo usługa z parametrami: philips_airfryer.adjust_time time=60 method=add. Przycisk pojawia się tylko, gdy jego pole jest wypełnione, i tylko jeśli odpowiada.",
  "Storage battery": "Magazyn energii",
  "💾 Stove saved": "💾 Piec zapisany",
  "A fan, a number or a select. Without it, the thermostat's fan modes are used, if it has any.":
    "Encja fan, number lub select. Bez niej używane są tryby wentylatora termostatu, jeśli je ma.",
  "A gas, pellet or wood boiler: flow, return, pressure, combustion.":
    "Kocioł gazowy, na pelet lub na drewno: zasilanie, powrót, ciśnienie, spalanie.",
  "A number or a select, 1 to 5 or P1 to P5: on the page it becomes the dots with minus and plus.":
    "Encja number lub select, od 1 do 5 albo od P1 do P5: na stronie staje się kropkami z minusem i plusem.",
  "A pellet stove in a room: the flame, the power, the fan and the hopper. More than one, too.":
    "Piec na pellet w pomieszczeniu: płomień, moc, wentylator i zbiornik. Także więcej niż jeden.",
  "A sensor with the alarm text or a binary_sensor: when it trips, the page shows the red banner with its words.":
    "Czujnik z treścią alarmu albo binary_sensor: gdy się włączy, strona pokazuje czerwony pasek z jego słowami.",
  "Add stove": "Dodaj piec",
  "An electric water heater, fed by the PV plant or not.":
    "Elektryczny podgrzewacz wody, zasilany z fotowoltaiki albo nie.",
  "As a percentage or in kg, like the boiler's; or a binary_sensor that turns on when the pellet is running low.":
    "W procentach lub w kg, jak w kotle; albo binary_sensor, który włącza się, gdy pelletu zaczyna brakować.",
  "Brazier cleaning": "Czyszczenie paleniska",
  "Check the stove's display.": "Sprawdź wyświetlacz pieca.",
  "Flame · Power · Pellet": "Płomień · Moc · Pelet",
  "For whoever has two hoppers: the page shows them side by side, Pellet 1 and Pellet 2, with the same threshold as the first.":
    "Dla tych, którzy mają dwa zbiorniki: strona pokazuje je obok siebie, Pelet 1 i Pelet 2, z tym samym progiem co pierwszy.",
  Ignition: "Rozpalanie",
  "In alarm": "Alarm",
  "Living room stove": "Piec w salonie",
  "Lower the power": "Zmniejsz moc",
  Modulating: "Modulacja",
  "No stove configured": "Nie skonfigurowano pieca",
  "On its own it covers nearly everything: on and off, the target, the room temperature and, if it has them, the fan modes.":
    "Sam wystarcza prawie do wszystkiego: włączanie i wyłączanie, wartość zadana, temperatura w pomieszczeniu i, jeśli je ma, tryby wentylatora.",
  "Pellet level, second hopper": "Poziom peletu, drugi zbiornik",
  "Pellet OK": "Pelletu wystarczy",
  "Pellet running low": "Kończy się pellet",
  "Power level": "Poziom mocy",
  "Raise the power": "Zwiększ moc",
  "Roof collectors and a tank: the fields are the ones below.":
    "Kolektory na dachu i zasobnik: pola są poniżej.",
  "Room temperature": "Temperatura w pomieszczeniu",
  "Save stove": "Zapisz piec",
  "Shutting down": "Wygaszanie",
  "Slow the fan down": "Zwolnij wentylator",
  "Speed the fan up": "Przyspiesz wentylator",
  Stove: "Piec",
  "Stove alarm": "Alarm pieca",
  "Stove controls": "Sterowanie piecem",
  "Stove phase": "Faza pieca",
  "Stove thermostat": "Termostat pieca",
  "Switch (when there is no thermostat)": "Przełącznik (gdy nie ma termostatu)",
  "The stove heats the room it stands in: the page draws the flame, the power, the fan, the flue and the hopper, and gives you the buttons for on and off, the target, the power and the fan. No field is required: with just the thermostat the page already has almost everything. With more than one, add them here and the page grows a row to switch between them.":
    "Piec ogrzewa pomieszczenie, w którym stoi: strona rysuje płomień, moc, wentylator, przewód kominowy i zbiornik, a do tego przyciski włączania i wyłączania, wartości zadanej, mocy i wentylatora. Żadne pole nie jest obowiązkowe: z samym termostatem strona ma już prawie wszystko. Jeśli masz więcej niż jeden, dodaj je tutaj, a na stronie pojawi się rząd do przełączania.",
  "The word the stove shows on its display: ignition, working, brazier cleaning, shutdown… If the page does not know it, it shows it as it is.":
    "Słowo, które piec pokazuje na wyświetlaczu: rozpalanie, praca, czyszczenie paleniska, wygaszanie… Jeśli strona go nie zna, pokazuje je tak, jak jest.",
  "Without it, the thermostat's own reading is used.":
    "Bez niego używany jest odczyt samego termostatu.",
  Working: "Praca",
  "Air conditioners out of season": "Klimatyzatory poza sezonem",
  "Radiators out of season": "Grzejniki poza sezonem",
  "They show: ${periodo}. Switched on, they show anyway.":
    "Widoczne: ${periodo}. Włączone pojawiają się mimo to.",
  "Show them anyway": "Pokaż mimo to",
  "🐠 The aquarium's entities": "🐠 Encje akwarium",
  "🦎 The terrarium's entities": "🦎 Encje terrarium",
  "🧽 Cleaning": "🧽 Sprzątanie",
  "🪣 The tank": "🪣 Zbiornik",
  Aquariums: "Akwaria",
