  Mister: "Zraszacz",
  "Not recorded yet: tap “Done today” on the day you clean it, and from then on the card counts the days.":
    "Jeszcze nie zapisano: dotknij „Zrobione dziś” w dniu sprzątania, a od tej pory karta będzie liczyć dni.",
  "One row per entity: temperature and pH with their ideal range, the water level, the lights, the filter and the heater. Empty ranges use the defaults: 24–27 °C and pH 6.5–7.5.":
    "Jeden wiersz na encję: temperatura i pH z idealnym zakresem, poziom wody, światła, filtr i grzałka. Puste zakresy przyjmują wartości domyślne: 24–27 °C i pH 6,5–7,5.",
  "One row per entity: warm-side and cool-side temperatures, humidity, lights, heat lamp, UVB, mister. Empty ranges use the defaults: 28–35 °C on the warm side, 22–28 °C on the cool side, humidity 40–80 %.":
    "Jeden wiersz na encję: temperatura strony ciepłej i chłodnej, wilgotność, światła, lampa grzewcza, UVB, zraszacz. Puste zakresy przyjmują wartości domyślne: 28–35 °C po ciepłej stronie, 22–28 °C po chłodnej, wilgotność 40–80 %.",
  "Optional: left empty, the terrarium reminds nobody to clean it. With a number the card says when it is due.":
    "Opcjonalne: puste pole oznacza, że terrarium nikomu nie przypomina o sprzątaniu. Z liczbą karta mówi, kiedy nadejdzie pora.",
  "Other pet": "Inne zwierzę",
  "Other pets": "Inne zwierzęta",
  "Other reading": "Inny pomiar",
  "Reservoir level": "Poziom zbiornika",
  "Take the ${quante} terrarium entities Home Assistant found":
    "Weź encje terrarium znalezione przez Home Assistant: ${quante}",
  "Temperature (cool side)": "Temperatura (strona chłodna)",
  "Temperature (warm side)": "Temperatura (strona ciepła)",
  Terrarium: "Terrarium",
  "Terrarium climate": "Klimat terrarium",
  Terrariums: "Terraria",
  "The pets of the house: one card each, with its photo and what concerns it — the bowl, the litter box, the water, the microchip door, the collar. Aquariums and terrariums too, as many as you have: each with its own entities.":
    "Zwierzaki domowe: dla każdego jedna karta, ze zdjęciem i tym, co go dotyczy — miska, kuweta, woda, drzwiczki z mikroczipem, obroża. Również akwaria i terraria, ile tylko masz: każde z własnymi encjami.",
