    "Strona bierze stąd temperaturę i proponowane sterowanie",
  "Your own controls": "Twoje własne sterowanie",
  "Heating · Cooling": "Grzanie · Chłodzenie",
  "It fills itself with the source dashboard's climate, split into the Cooling and Heating tabs like the Climate section: air conditioners in cooling, radiators and thermostats in heating, heat pumps in both.":
    "Wypełnia się sama klimatem z panelu źródłowego, podzielonym na karty Chłodzenie i Grzanie jak w sekcji Klimat: klimatyzatory w chłodzeniu, grzejniki i termostaty w grzaniu, pompy ciepła w obu.",
  "Opens on": "Otwiera się na",
  "Page type": "Typ strony",
  "Shown on the tab at the top": "Widoczna na karcie u góry",
  "The wall tablet's panel. Choose the pages — the tabs at the top — and what each one holds. On the tablet, holding the clock for two seconds brings you back here.":
    "Panel tabletu ściennego. Wybierz strony — karty u góry — i co ma być na każdej. Na tablecie przytrzymanie zegara przez dwie sekundy przywraca cię tutaj.",
  "All blinds": "Wszystkie rolety",
