  "Temperature · Humidity · Lights": "Temperatura · Wilgotność · Światła",
  "Temperature on the rest screen": "Temperatura na ekranie spoczynku",
  "The source dashboard's cameras, all together; a tap opens one full screen.":
    "Kamery pulpitu źródłowego, wszystkie razem; dotknięcie otwiera jedną na pełnym ekranie.",
  "To the grid": "Do sieci",
  "Unsaved changes: the tablet sees them after «Save».":
    "Niezapisane zmiany: tablet zobaczy je po «Zapisz».",
  "Empty: the ones from the dashboard's Music section": "Puste: te z sekcji Muzyka pulpitu",
  "No player: add them in the Music section or here in the config":
    "Brak odtwarzacza: dodaj je w sekcji Muzyka lub tutaj w konfiguracji",
  Players: "Odtwarzacze",
  "The ones chosen here, in this order": "Wybrane tutaj, w tej kolejności",
  "The player that's playing, big, with cover, buttons, volume and sources; beside it the others, each with its own play. A tap on a player brings it up big.":
    "Odtwarzacz, który gra, w dużym rozmiarze, z okładką, przyciskami, głośnością i źródłami; obok pozostałe, każdy ze swoim play. Dotknięcie odtwarzacza pokazuje go w dużym rozmiarze.",
  "What's playing at home": "Co gra w domu",
