  "Start and shutdown": "Start i wyłączenie",
  "Stop (optional)": "Zatrzymanie (opcjonalnie)",
  "The pages in a column of big buttons on the left, like on control-room panels. Landscape only: in portrait and on small screens the tabs at the top stay":
    "Strony w kolumnie dużych przycisków po lewej, jak na pulpitach reżyserskich. Tylko w poziomie: w pionie i na małych ekranach zostają zakładki u góry",
  Zoom: "Zoom",
  "☀️ Panel": "☀️ Kolektor",
  "🎛️ Controls": "🎛️ Sterowanie",
  "🔁 Circuit": "🔁 Obieg",
  "🛢️ Tank": "🛢️ Zasobnik",
  "Power sensor (sensor, W)": "Czujnik mocy (sensor, W)",
  "Pressure sensor (sensor, bar)": "Czujnik ciśnienia (sensor, bar)",
  "Solar pump (state)": "Pompa solarna (stan)",
  "Switch to turn on and off (switch or input_boolean)":
    "Przełącznik do włączania i wyłączania (switch lub input_boolean)",
  "Tank bottom": "Zasobnik dół",
  "Tank top": "Zasobnik góra",
  "Tells whether the pump runs (binary_sensor or switch): makes the light flow in the pipes":
    "Mówi, czy pompa pracuje (binary_sensor lub switch): puszcza światło w rurach",
  "Temperature sensor (sensor, °C)": "Czujnik temperatury (sensor, °C)",
