    "Czujnik temperatury (sensor, °C): kolektor minus zasobnik",
  "Valve (valve) or switch (switch); empty uses valve.chiave_solare_termico":
    "Zawór (valve) lub przełącznik (switch); pusty używa valve.chiave_solare_termico",
  "Valve with a position (cover): open above zero": "Zawór z pozycją (cover): otwarty powyżej zera",
  Command: "Polecenie",
  "▲ command": "Polecenie ▲",
  "▼ command": "Polecenie ▼",
  "Start command": "Polecenie startu",
  "Mute command": "Polecenie wyciszenia",
  "Stop command": "Polecenie zatrzymania",
  "The dashboard doesn't know the arrows of ${nome}: the remote shows among the commands as an on/off button. Its commands go in «Other commands», as remote.name:command.":
    "Panel nie zna strzałek ${nome}: pilot pojawia się wśród poleceń jako przycisk wł./wył. Jego polecenia dodaje się w «Inne polecenia», jako remote.name:command.",
  "Home Assistant doesn't say which integration this remote belongs to: it shows among the commands as an on/off button. Its commands go in «Other commands», as remote.name:command.":
    "Home Assistant nie mówi, do jakiej integracji należy ten pilot: pojawia się wśród poleceń jako przycisk wł./wył. Jego polecenia dodaje się w «Inne polecenia», jako remote.name:command.",
  "Device (optional)": "Urządzenie (opcjonalnie)",
  "Remote device": "Urządzenie pilota",
  "Optional: the «device» of remote.send_command": "Opcjonalnie: «device» dla remote.send_command",
  "The live picture on the left, arrows and zoom on the right, presets below. Each button presses an entity already in Home Assistant: a camera button, a script with onvif.ptz, or a remote with the command to send. A button without an entity stays off.":
    "Obraz na żywo po lewej, strzałki i zoom po prawej, presety pod spodem. Każdy przycisk naciska encję, która już jest w Home Assistant: przycisk kamery, skrypt z onvif.ptz albo pilota (remote) z poleceniem do wysłania. Przycisk bez encji pozostaje wyłączony.",
  "Read level (optional)": "Odczytany poziom (opcjonalnie)",
  "Each channel is an upright fader with its mute: a player's volume, or a number (number, input_number) like a mixer's dB. A sensor becomes a meter you look at; a remote gets ▲ / ▼ and mute, each with its own command (remote.send_command). Mute is the player's own, a switch (on means muted), a remote or a button to press.":
    "Każdy kanał to pionowy suwak z wyciszeniem: głośność odtwarzacza albo liczba (number, input_number) jak dB miksera. Czujnik staje się miernikiem do oglądania; pilot (remote) ma ▲ / ▼ i wyciszenie, każde z własnym poleceniem (remote.send_command). Wyciszenie to wyciszenie odtwarzacza, przełącznik (włączony znaczy wyciszony), pilot albo przycisk do naciśnięcia.",
  "What the integration publishes next to the player — a TV's power switch, the input dropdown, a scene: button.*, select.*, switch.* entities (plus input_*, script.*, scene.*). A remote.* turns on and off; written remote.name:command (for example remote.amp:volume_up) it sends that command. They appear on the card under the playback controls.":
    "To, co integracja publikuje obok odtwarzacza — włącznik zasilania telewizora, lista źródeł, scena: encje button.*, select.*, switch.* (oraz input_*, script.*, scene.*). Pilot remote.* włącza się i wyłącza; zapisany jako remote.name:command (na przykład remote.amp:volume_up) wysyła to polecenie. Pojawiają się na karcie pod przyciskami odtwarzania.",
  "Scale: to": "Skala: do",
  "Scale: from": "Skala: od",
  "A button.*, select.*, switch.* or remote.* entity is required (also remote.name:command) — or input_button, input_select, input_boolean, script, scene.":
    "Wymagana jest encja button.*, select.*, switch.* lub remote.* (także remote.name:command) — albo input_button, input_select, input_boolean, script, scene.",
  "A sensor with the level": "Czujnik z poziomem",
  "Empty: turns on": "Puste: włącza",
  "Empty: turns off": "Puste: wyłącza",
  "${inserite} of ${tutte} armed": "${inserite} z ${tutte} uzbrojone",
  "Add a command": "Dodaj polecenie",
  "Add a partition": "Dodaj strefę",
  "Add a reading": "Dodaj odczyt",
  "Alarm · ${quante} areas": "Alarm · ${quante} strefy",
  "Alarm partitions": "Strefy alarmu",
  "Buttons next to the readings: locks (lock and unlock), scripts, buttons, scenes, switches, blinds. A remote turns on and off; written remote.name:command it sends that command.":
    "Przyciski obok odczytów: zamki (zamykanie i otwieranie), skrypty, przyciski, sceny, przełączniki, rolety. Pilot (remote) się włącza i wyłącza; zapisany jako remote.name:command wysyła to polecenie.",
  "Empty: all the ones from the dashboard's Security section":
    "Puste: wszystkie z sekcji Bezpieczeństwo pulpitu",
  "Intercom / camera": "Domofon / kamera",
  "Leaving and who is home": "Wyjście i kto jest w domu",
  "All clear": "Wszystko w porządku",
  "Open doors": "Otwarte drzwi",
  "Open doors and windows": "Otwarte drzwi i okna",
  "since ${ora}": "od ${ora}",
  "The entries declared in the Security section": "Wejścia zadeklarowane w sekcji Bezpieczeństwo",
  "The ones chosen here, in this order: each with its state and its buttons, the ones its panel accepts":
    "Wybrane tutaj, w tej kolejności: każda ze swoim stanem i przyciskami, które akceptuje jej centrala",
  "Under the alarm, each with its value: doors and windows (binary_sensor), sensors, locks, blinds. Two or more doors or windows become a single count, «Open windows: 2»; a tap lists them.":
    "Pod alarmem, każdy ze swoją wartością: drzwi i okna (binary_sensor), czujniki, zamki, rolety. Dwoje lub więcej drzwi czy okien staje się jednym licznikiem, «Otwarte okna: 2»; dotknięcie je wymienia.",
  "Water!": "Woda!",
  "Next to the people": "Obok osób",
  "No extra reading: the row says whether it is up or down, nothing else.":
    "Brak dodatkowych odczytów: wiersz mówi tylko, czy działa, czy nie.",
  Nothing: "Nic",
  "The sensors that tell more about this device than “up” and “down” — ping latency, packet loss, uptime, the last time it was seen: sensor.*, binary_sensor.*, number.* entities. They show under its row on the MiniPC page, with their own name and unit.":
    "Czujniki, które mówią o tym urządzeniu więcej niż „działa” i „nie działa” — opóźnienie pinga, utracone pakiety, czas pracy, kiedy było ostatnio widziane: encje sensor.*, binary_sensor.*, number.*. Pojawiają się pod jego wierszem na stronie MiniPC, z własną nazwą i jednostką.",
  "Classic bell": "Klasyczny dzwonek",
  Ding: "Ding",
  "Ding dong": "Ding-dong",
  "Even with the screen off: it turns on at full brightness and the intercom takes the whole screen, like a call.":
    "Nawet przy wyłączonym ekranie: włącza się na pełną jasność, a domofon zajmuje cały ekran, jak połączenie.",
  "It rang at": "Dzwoniono o",
