  "Start ${a.name} on solar": "Uruchom ${a.name} ze słońca",
  "Take out: ${r.name}": "Wystaw: ${r.name}",
  "The alarm has been triggered.": "Alarm został uruchomiony.",
  "The alarm is going off": "Alarm wyje",
  "the car": "auto",
  "The house assistant watches the house for you and tells you the most important thing to do right now: lights left on in an empty house, a window open with the heating on, rain on its way, the laundry done, spare solar power. It learns from what you dismiss, and remembers it for the whole household. On a computer or tablet it sits to the right of the people, on a phone below them.":
    "Asystent domu pilnuje domu za ciebie i mówi, co jest teraz najważniejsze: światła zapalone w pustym domu, otwarte okno przy włączonym ogrzewaniu, nadchodzący deszcz, skończone pranie, nadwyżka ze słońca. Uczy się z tego, co odrzucasz, i pamięta to dla całego domu. Na komputerze i tablecie jest po prawej od osób, na telefonie pod nimi.",
  "The house is drawing ${kw} kW from the grid": "Dom pobiera ${kw} kW z sieci",
  "The house is empty and ${nomi(aperte, l)} is unlocked":
    "Dom jest pusty, a ${nomi(aperte, l)} nie jest zamknięte na klucz",
  "The leak sensor is wet: shall I close the valve?": "Czujnik zalania jest mokry: zamknąć zawór?",
  "The leak sensor is wet.": "Czujnik zalania jest mokry.",
  "There are ${quanti} updates to install": "Aktualizacje do zainstalowania: ${quanti}",
  "There is an update to install": "Jest aktualizacja do zainstalowania",
  Tonight: "Wieczorem",
  "Turn it off until someone is back?": "Wyłączyć, dopóki ktoś nie wróci?",
  "Turn it off?": "Wyłączyć?",
  "Turn off climate": "Wyłącz klimat",
  "Turn them off?": "Wyłączyć je?",
  urgent: "pilne",
  "Water detected: ${nomi(bagnati, l)}": "Wykryto wodę: ${nomi(bagnati, l)}",
  "What it talks about": "O czym mówi",
  "Worth a check.": "Warto sprawdzić.",
  "You left with ${nomi(aperte, l)} open": "Wyszliście, a ${nomi(aperte, l)} jest otwarte",
  "You're near the limit: can ${nomi(accesi, l)} wait?":
    "Jesteś blisko limitu: czy ${nomi(accesi, l)} może poczekać?",
  "You're near the meter's limit.": "Jesteś blisko limitu licznika.",
  "You're out and ${g.name} is open": "Nie ma was, a ${g.name} jest otwarta",
  "e.g. 30": "np. 30",
  "End-of-cycle delay under ${minuti} minutes: 0 W pauses mid-programme look like the end of the cycle.":
    "Opóźnienie końca cyklu poniżej ${minuti} minut: przerwy 0 W w środku programu wyglądają jak koniec cyklu.",
  "Recommended: running ${a} W, standby ${b} W, delay ${minuti} min.":
    "Zalecane: praca ${a} W, czuwanie ${b} W, opóźnienie ${minuti} min.",
  "Running threshold under 1 W: a lit display is enough to show Running.":
    "Próg pracy poniżej 1 W: wystarczy włączony wyświetlacz, by pokazać „Pracuje”.",
  "Standby threshold at or above the running one: standby can never show.":
    "Próg czuwania równy lub wyższy od progu pracy: czuwanie nigdy się nie pojawi.",
  "Use the recommended values": "Użyj zalecanych wartości",
  "With these values one cycle can turn into many mini-cycles.":
    "Przy tych wartościach jeden cykl może zamienić się w wiele minicykli.",
  "System off": "Instalacja wyłączona",
  "Battery power": "Moc baterii",
  "Battery: charge": "Bateria: naładowanie",
  "Battery: power": "Bateria: moc",
  "Big live numbers. Left empty, they come from the source dashboard's Energy section, with its direction.":
    "Duże liczby na żywo. Puste są brane z sekcji Energia panelu źródłowego, z jej kierunkiem.",
  "Charging power": "Moc ładowania",
  "Discharging power": "Moc rozładowania",
