  "If your inverter writes them the other way round: grid positive when feeding in, battery positive when charging":
    "Jeśli falownik zapisuje je odwrotnie: sieć dodatnia przy oddawaniu, bateria dodatnia przy ładowaniu",
  "In %": "W %",
  "One signed sensor, or two separate ones": "Jeden czujnik ze znakiem albo dwa osobne",
