  "All optional, one per type. Temperature, humidity, feels-like and wind are the same fields as the Home header; rain and rate are the ones Irrigation already uses. They are chosen once and apply everywhere.":
    "Wszystkie opcjonalne, jeden na typ. Temperatura, wilgotność, odczuwalna i wiatr to te same pola co w nagłówku strony głównej; deszcz i natężenie to te, których używa już Nawadnianie. Wybiera się je raz i obowiązują wszędzie.",
