  "the home did not answer": "dom nie odpowiedział",
  "The home that does it by itself: lights, climate, shutters and alerts that start when needed.":
    "Dom, który działa sam: światła, klimat, rolety i powiadomienia, które ruszają, gdy trzeba.",
  "The home's automations": "Automatyzacje domu",
