    "Lista i zapis przechodzą przez dodatek GdAHome: tutaj go nie ma.",
  "the new automation": "nowa automatyzacja",
  "then → ${allora}": "wtedy → ${allora}",
  "This automation lives in a Home Assistant file: here you turn it on, off and run it, and it is changed there.":
    "Ta automatyzacja jest w pliku Home Assistant: tutaj ją włączasz, wyłączasz i uruchamiasz, a zmienia się ją tam.",
  "This automation uses advanced features (a choice between cases, a template, a blueprint…): here you can turn it on and off, run it, rename it and change its room. For the rest:":
    "Ta automatyzacja używa funkcji zaawansowanych (wybór między przypadkami, szablon, blueprint…): tutaj możesz ją włączyć, wyłączyć, uruchomić, zmienić nazwę i pomieszczenie. Resztę:",
