  "You'll find it there and Home Assistant runs it.":
    "Znajdziesz ją tam, a wykonuje ją Home Assistant.",
  "🚨 Removed": "🚨 Usunięto",
  "🚨 Saved: the house knows when it goes off": "🚨 Zapisano: dom wie, kiedy alarm się włącza",
  "A sensor that names the zone. Empty: the house looks at which door, window or motion turned on last.":
    "Czujnik podający strefę. Puste: dom sprawdza, które drzwi, okno lub ruch włączyły się ostatnie.",
  "at rest": "w spoczynku",
  "Empty means “on”.": "Puste oznacza „on”.",
  "For the “Siren off” button in the notification and in Security.":
    "Dla przycisku „Wyłącz syrenę” w powiadomieniu i w Bezpieczeństwie.",
  NEW: "NOWE",
  "Siren (optional)": "Syrena (opcjonalnie)",
