  "Siren on": "Syrena włączona",
  "The entity that says the alarm is going off: a switch, a sensor or a helper. When it reads “triggered” Security, the Home tile and the wall panel turn red, and the house sends the urgent notification.":
    "Encja, która mówi, że alarm się włączył: przełącznik, czujnik lub pomocnik. Gdy pokazuje „wyzwolony”, Bezpieczeństwo, kafelek Home i panel ścienny robią się czerwone, a dom wysyła pilne powiadomienie.",
  "The value that means “triggered”": "Wartość oznaczająca „wyzwolony”",
