  "assign them": "przypisz je",
  "Automatic circles from rooms": "Automatyczne koła z pomieszczeń",
  "Confirm the suggestions": "Potwierdź sugestie",
  "Each plant has its own meter and its own limit: above the threshold the alert says which plant. The one you had before now belongs to the first plant.":
    "Każda instalacja ma swój licznik i swój limit: powyżej progu alert mówi która. Dotychczasowy próg należy teraz do pierwszej instalacji.",
  "Group by floor": "Grupuj według piętra",
  "no plant": "brak instalacji",
  "One circle per floor; tap it to see its rooms.":
    "Jedno koło na piętro; dotknij, aby zobaczyć pomieszczenia.",
  "Power threshold · one per meter": "Próg mocy · jeden na licznik",
  "suggested: its floor is covered by": "sugestia: jego piętro obejmuje",
  "suggested: the same power is already a load of": "sugestia: ta sama moc jest już obciążeniem w",
  "The house appliances become per-room circles in the flow. Each one goes in its meter's flow: until you say which, it shows up in none.":
    "Urządzenia domu stają się w przepływie kołami według pomieszczeń. Każde trafia do przepływu swojego licznika: dopóki tego nie wskażesz, nie pojawia się w żadnym.",
  "The meter that measures it: it shows up in that plant's flow.":
    "Licznik, który je mierzy: pojawia się w przepływie tej instalacji.",
  "The rooms have no floor: you can set one in the Rooms page of the config.":
    "Pomieszczenia nie mają piętra: możesz je ustawić na stronie Pomieszczenia w konfiguracji.",
  "The rooms on the chosen floors go to this plant by themselves, with their appliances.":
    "Pomieszczenia z wybranych pięter same trafiają do tej instalacji, razem z urządzeniami.",
  "This plant's rooms, with their appliances; the rest under «Other».":
    "Pomieszczenia tej instalacji z ich urządzeniami; reszta w «Inne».",
  "to confirm": "do potwierdzenia",
