  "The dashboard's illustrations": "Ilustracje pulpitu",
  "The photo is saved in the GdAHome add-on, with the dashboard's other photos. Before it leaves, the phone shrinks it to 1200 px; it goes through no outside server.":
    "Zdjęcie zapisuje się w dodatku GdAHome, razem z innymi zdjęciami pulpitu. Przed wysłaniem telefon zmniejsza je do 1200 px; nie przechodzi przez żaden zewnętrzny serwer.",
  "The usual drawing comes back.": "Wraca zwykły rysunek.",
