  "change it in More settings › Weather": "zmienisz w Więcej ustawień › Pogoda",
  "Choose the weather entity in ⚙️ Config › On the wall › More settings › Weather, or add a weather integration in Home Assistant.":
    "Wybierz encję pogody w ⚙️ Config › Na ścianie › Więcej ustawień › Pogoda albo dodaj integrację pogodową w Home Assistant.",
  "Choose the weather entity in More settings › Weather, or add a weather integration in Home Assistant":
    "Wybierz encję pogody w Więcej ustawień › Pogoda albo dodaj integrację pogodową w Home Assistant",
  "Forecast on its way…": "Prognoza w drodze…",
  "Full-page weather: what it's like now, big, with feels-like, humidity, wind and pressure, then the coming hours and days. It uses the same weather the tablet shows at the top and on the rest screen.":
    "Pogoda na całą stronę: jak jest teraz, w dużym formacie, z temperaturą odczuwalną, wilgotnością, wiatrem i ciśnieniem, a potem najbliższe godziny i dni. Używa tej samej pogody, którą tablet pokazuje u góry i na ekranie spoczynku.",
  gusts: "porywy",
